// CyberLab catalog part 6 — PHASE 3 lessons (Levels 8–11 completion).
// Same standard as catalog.ts/catalog5.ts: full lesson format, real complete
// code for the stated environment, 3-question quiz, validated practical per
// lesson. Facts: OWASP Top 10 categories, RFC numbers, tool syntax and
// framework versions are the stable published ones named in each lesson's
// reference line (verified 2026-11-12 — see DATA-PLAN.md). No CVE IDs,
// scores, dates or breach stories are asserted anywhere in this file.
// Labs run ONLY against the learner's own localhost / VM / local demo apps.

import type { Lesson } from "./catalog";
import type { Checkpoint, LevelFinal, Practical } from "./catalog3";
import type { Ctf, Lab, Mission } from "./catalog2";

const V = "1.0";
const REV = "2026-11-12";
const TESTED = "Complete example, reviewed line by line for syntax in the stated environment. Not executed inside CyberLab — run it in your own lab to see it live.";
const VER = "verified 2026-11-12";

type Spec = Omit<Lesson, "version" | "reviewed" | "limitations">;
function L(s: Spec): Lesson {
  return { ...s, version: V, reviewed: REV, limitations: TESTED };
}

