    code: { lang: "python", title: "password_store.py — scrypt password storage + verification (complete, Python 3.10+, stdlib only)", code: "import hashlib, hmac, secrets\n\n# scrypt work factors (OWASP Cheat Sheet minimums class): n=2**14, r=8, p=1\ndef hash_password(password: str) -> str:\n    salt = secrets.token_bytes(16)\n    dk = hashlib.scrypt(password.encode(), salt=salt, n=16384, r=8, p=1, dklen=32)\n    return f\"scrypt${salt.hex()}${dk.hex()}\"\n\ndef verify_password(password: str, stored: str) -> bool:\n    try:\n        scheme, salt_hex, hash_hex = stored.split(\"$\")\n        if scheme != \"scrypt\":\n            return False\n        dk = hashlib.scrypt(password.encode(), salt=bytes.fromhex(salt_hex),\n                            n=16384, r=8, p=1, dklen=32)\n        return hmac.compare_digest(dk.hex(), hash_hex)\n    except (ValueError, TypeError):\n        return False\n\nstored = hash_password(\"correct-horse-battery-staple\")\nprint(\"stored:\", stored[:40] + \"...\")\nprint(\"right password verifies:\", verify_password(\"correct-horse-battery-staple\", stored))\nprint(\"wrong password verifies:\", verify_password(\"correct-horse-battery-staplE\", stored))\nprint(\"same password, new hash differs:\", hash_password(\"correct-horse-battery-staple\") != stored)", output: "stored: scrypt$<32 hex salt chars>$...\nright password verifies: True\nwrong password verifies: False\nsame password, new hash differs: True", lines: ["hashlib.scrypt is standard-library Python — no installs, no excuses for MD5.", "A fresh random salt per password is generated inside hash_password, never reused.", "The stored string carries scheme + salt + hash together, so verification needs no extra columns.", "compare_digest makes the final comparison constant-time; == would leak match length via timing.", "Run it with: python3 password_store.py"] },
