    code: { lang: "python", title: "reset_tokens.py — expiring, single-use, hash-stored reset tokens (complete, Python 3.10+, stdlib only)", code: "import hashlib, secrets, time\n\nSTORE = {}  # user -> (sha256_of_token, expiry_epoch)  # a DB table in real apps\nTTL_SECONDS = 30 * 60\n\ndef issue_token(user: str) -> str:\n    token = secrets.token_urlsafe(32)\n    digest = hashlib.sha256(token.encode()).hexdigest()\n    STORE[user] = (digest, time.time() + TTL_SECONDS)\n    return token  # this raw token goes in the email link — never stored\n\ndef consume_token(user: str, token: str) -> bool:\n    rec = STORE.get(user)\n    if rec is None:\n        return False\n    digest, expiry = rec\n    if time.time() > expiry:\n        del STORE[user]\n        return False\n    ok = secrets.compare_digest(hashlib.sha256(token.encode()).hexdigest(), digest)\n    if ok:\n        del STORE[user]  # single-use: success consumes the token\n    return ok\n\nt = issue_token('nadia')\nprint('first use accepted: ', consume_token('nadia', t))\nprint('replay rejected:    ', consume_token('nadia', t))\nprint('wrong token rejected:', consume_token('nadia', 'not-the-token'))\nt2 = issue_token('nadia')\nSTORE['nadia'] = (STORE['nadia'][0], time.time() - 1)  # simulate expiry\nprint('expired rejected:   ', consume_token('nadia', t2))", output: "first use accepted:  True\nreplay rejected:     False\nwrong token rejected: False\nexpired rejected:    False", lines: ["secrets.token_urlsafe(32) gives 256 bits of randomness — tokens are unguessable, not sequential.", "Only the SHA-256 of the token is stored: a leaked token table yields no working tokens.", "Expiry and single-use are enforced in consume_token — the two design requirements, as code.", "compare_digest again for the secret comparison (the crypto-failures lesson's habit).", "Run it with: python3 reset_tokens.py"] },
